use crate::error::Result;
use crate::git::service::GitService;
use std::path::Path;

/// Structured finding from code review
#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
pub struct ReviewFinding {
    pub category: String,
    pub severity: String, // "HIGH", "MEDIUM", "LOW", "PASS"
    pub title: String,
    pub details: String,
    pub line_hint: Option<String>,
}

/// Scorecard and audit report generated by the code reviewer
#[derive(Debug, Clone, serde::Serialize, serde::Deserialize)]
pub struct ReviewReport {
    pub total_score: u32,
    pub files_audited: usize,
    pub findings: Vec<ReviewFinding>,
    pub summary: String,
}

/// Multi-dimensional code review engine evaluating git changes across 5 critical pillars.
pub struct GitReviewer;

impl GitReviewer {
    /// Discovers workspace source files for verification and review when `.git` is absent
    /// or has no uncommitted diff (checking active transaction snapshots first, then walking source directories).
    pub fn discover_workspace_source_files(workspace_root: &Path) -> Vec<String> {
        if let Ok(Some(active_tx)) =
            crate::session::transaction::TransactionManager::get_active(workspace_root)
        {
            let mut tx_files: Vec<String> = active_tx
                .files
                .iter()
                .map(|f| f.relative_path.clone())
                .filter(|rel| workspace_root.join(rel).is_file())
                .collect();
            tx_files.sort();
            tx_files.dedup();
            if !tx_files.is_empty() {
                return tx_files;
            }
        }

        let mut discovered = Vec::new();
        let walker = ignore::WalkBuilder::new(workspace_root)
            .max_depth(Some(5))
            .hidden(true)
            .git_ignore(true)
            .build();

        for entry in walker.flatten() {
            let path = entry.path();
            if !path.is_file() {
                continue;
            }
            let Ok(rel) = path.strip_prefix(workspace_root) else {
                continue;
            };
            let rel_str = rel.to_string_lossy().replace('\\', "/");
            if rel_str.is_empty()
                || rel_str.starts_with("node_modules/")
                || rel_str.starts_with("target/")
                || rel_str.starts_with("dist/")
                || rel_str.starts_with("build/")
                || rel_str.starts_with(".next/")
                || rel_str.starts_with(".minicode/")
                || rel_str.starts_with("minikit_docs/")
                || rel_str.starts_with("onpkg_docs/")
                || rel_str.starts_with("screenshots/")
                || rel_str.starts_with(".git/")
            {
                continue;
            }
            let ext = path
                .extension()
                .and_then(|e| e.to_str())
                .unwrap_or("")
                .to_ascii_lowercase();
            if matches!(
                ext.as_str(),
                "rs" | "ts"
                    | "tsx"
                    | "js"
                    | "jsx"
                    | "mjs"
                    | "cjs"
                    | "css"
                    | "html"
                    | "py"
                    | "go"
                    | "vue"
                    | "svelte"
                    | "dart"
            ) {
                discovered.push(rel_str);
            }
        }
        discovered.sort();
        discovered.dedup();
        discovered
    }

    /// Audits uncommitted or staged changes in the workspace (or workspace source files in non-git workspaces)
    /// and produces a markdown review scorecard.
    pub async fn review_workspace(
        workspace_root: &Path,
        staged_only: bool,
    ) -> Result<ReviewReport> {
        let git = GitService::new(workspace_root.to_path_buf());
        let (diff_text, target_files) = if git.is_git_repo().await {
            let diff_text = git.diff(staged_only, None).await?;
            let status = git.get_status().await?;

            let target_files = if staged_only {
                status.staged
            } else {
                let mut all = status.staged;
                all.extend(status.unstaged);
                all.sort();
                all.dedup();
                all
            };

            if target_files.is_empty() && diff_text.trim().is_empty() {
                if staged_only {
                    return Ok(ReviewReport {
                        total_score: 100,
                        files_audited: 0,
                        findings: vec![],
                        summary: "✔ Working tree is completely clean — zero staged diffs to audit."
                            .to_string(),
                    });
                }
                let fallback_files = Self::discover_workspace_source_files(workspace_root);
                if fallback_files.is_empty() {
                    return Ok(ReviewReport {
                        total_score: 100,
                        files_audited: 0,
                        findings: vec![],
                        summary:
                            "✔ Working tree is completely clean — zero uncommitted diffs to audit."
                                .to_string(),
                    });
                }
                let mut synth_diff = String::new();
                for rel in &fallback_files {
                    if let Ok(content) = std::fs::read_to_string(workspace_root.join(rel)) {
                        synth_diff.push_str(&format!("+++ b/{}\n", rel));
                        for line in content.lines() {
                            synth_diff.push_str(&format!("+{}\n", line));
                        }
                    }
                }
                (synth_diff, fallback_files)
            } else {
                (diff_text, target_files)
            }
        } else {
            let fallback_files = Self::discover_workspace_source_files(workspace_root);
            if fallback_files.is_empty() {
                return Ok(ReviewReport {
                    total_score: 100,
                    files_audited: 0,
                    findings: vec![],
                    summary: "ℹ Workspace is not a git repository.".to_string(),
                });
            }
            let mut synth_diff = String::new();
            for rel in &fallback_files {
                if let Ok(content) = std::fs::read_to_string(workspace_root.join(rel)) {
                    synth_diff.push_str(&format!("+++ b/{}\n", rel));
                    for line in content.lines() {
                        synth_diff.push_str(&format!("+{}\n", line));
                    }
                }
            }
            (synth_diff, fallback_files)
        };

        let mut findings = Vec::new();
        let mut score = 100_u32;
        let mut low_deductions = 0_u32;

        // 1. Secret & Sensitive Data Audit + Lexical Code Quality Audit
        let mut current_file = String::new();
        let mut pending_cfg_test = false;
        let mut in_inline_test_scope = false;
        let mut test_brace_depth: i32 = 0;

        for line in diff_text.lines() {
            if let Some(stripped) = line.strip_prefix("+++ b/") {
                current_file = stripped.trim().to_string();
                pending_cfg_test = false;
                in_inline_test_scope = false;
                test_brace_depth = 0;
                continue;
            }

            // Track inline `#[cfg(test)]` scope boundaries across context and added lines
            if !line.starts_with("---") && !line.starts_with("@@") {
                let raw_code = line
                    .strip_prefix('+')
                    .or_else(|| line.strip_prefix(' '))
                    .unwrap_or("");
                let code_only = crate::utils::strings::strip_code_strings_and_comments(raw_code);
                let trimmed_code = code_only.trim();

                if trimmed_code.starts_with("#[cfg(test)]")
                    || trimmed_code.starts_with("#[test]")
                    || trimmed_code.starts_with("#[tokio::test")
                {
                    pending_cfg_test = true;
                }

                if pending_cfg_test || in_inline_test_scope {
                    let opens = code_only.chars().filter(|&c| c == '{').count() as i32;
                    let closes = code_only.chars().filter(|&c| c == '}').count() as i32;
                    if pending_cfg_test && opens > 0 {
                        in_inline_test_scope = true;
                        pending_cfg_test = false;
                    }
                    if in_inline_test_scope {
                        test_brace_depth += opens - closes;
                        if test_brace_depth <= 0 {
                            in_inline_test_scope = false;
                            test_brace_depth = 0;
                        }
                    }
                }
            }

            if line.starts_with('+') && !line.starts_with("+++") {
                let added = line[1..].trim();
                let uncommented = crate::utils::strings::strip_line_comments(added);
                let uncommented = uncommented.trim();
                if uncommented.is_empty() || uncommented.starts_with('*') {
                    continue;
                }

                let code_only = crate::utils::strings::strip_code_strings_and_comments(added);
                let code_only = code_only.trim();

                let is_test = current_file.contains("test")
                    || current_file.contains("spec")
                    || current_file.starts_with("tests/")
                    || in_inline_test_scope
                    || pending_cfg_test;
                let is_cli_entrypoint =
                    current_file == "src/main.rs" || current_file.ends_with("/main.rs");

                if !uncommented.contains("env::")
                    && !uncommented.contains("process.env")
                    && !uncommented.contains("std::env")
                    && !uncommented.contains("import.meta.env")
                    && crate::sandbox::redact::SecretRedactor::global().redact(uncommented)
                        != uncommented
                {
                    findings.push(ReviewFinding {
                        category: "Security & Secret Leakage".to_string(),
                        severity: "HIGH".to_string(),
                        title: "Potential Hardcoded Secret / Credential".to_string(),
                        details: format!(
                            "Added line matches a credential or secret pattern: `{}`",
                            crate::sandbox::redact::SecretRedactor::global().redact(added)
                        ),
                        line_hint: Some(
                            crate::sandbox::redact::SecretRedactor::global().redact(line),
                        ),
                    });
                    score = score.saturating_sub(25);
                }

                // 2. Unsafe / Panic Patterns (for Rust production code only, not tests or strings/comments)
                if !is_test && (code_only.contains(".unwrap()") || code_only.contains(".expect(")) {
                    findings.push(ReviewFinding {
                        category: "Correctness & Invariant Safety".to_string(),
                        severity: "MEDIUM".to_string(),
                        title: "Explicit Panic / Unwrap Pattern".to_string(),
                        details: format!("Prefer proper `?` error propagation with `thiserror`/`anyhow` instead of `.unwrap()`: `{}`", added),
                        line_hint: Some(line.to_string()),
                    });
                    score = score.saturating_sub(10);
                }

                // 3. Debug logging in library code (exclude tests, CLI entrypoint, and strings/comments)
                if !is_test
                    && !is_cli_entrypoint
                    && (code_only.contains("println!")
                        || code_only.contains("eprintln!")
                        || code_only.contains("console.log"))
                {
                    findings.push(ReviewFinding {
                        category: "Architecture & Observability".to_string(),
                        severity: "LOW".to_string(),
                        title: "Stdout Debug Statement".to_string(),
                        details: format!("Use structured logging (`tracing::debug!`, `tracing::info!`) instead of raw stdout: `{}`", added),
                        line_hint: Some(line.to_string()),
                    });
                    Self::deduct_low_capped(&mut score, &mut low_deductions, 3);
                }
            }
        }

        // 4. Missing Tests Check
        let has_code_changes = target_files
            .iter()
            .any(|f| f.ends_with(".rs") || f.ends_with(".ts") || f.ends_with(".py"));
        let has_test_changes = target_files
            .iter()
            .any(|f| f.contains("test") || f.contains("spec"));

        if has_code_changes && !has_test_changes {
            findings.push(ReviewFinding {
                category: "Verification & Test Coverage".to_string(),
                severity: "MEDIUM".to_string(),
                title: "Code Changes Detected Without Associated Tests".to_string(),
                details:
                    "Source code was modified without additions in `tests/` or unit test blocks."
                        .to_string(),
                line_hint: None,
            });
            score = score.saturating_sub(15);
        }

        // 5. Structural & Public API Impact Analysis (DiffProjector)
        if let Ok(projection) = crate::git::diff_projector::DiffProjector::project_workspace_diff(
            workspace_root,
            staged_only,
            None,
        )
        .await
        {
            for b in projection.breaking_changes {
                findings.push(ReviewFinding {
                    category: "Structural & Public API Impact".to_string(),
                    severity: "HIGH".to_string(),
                    title: format!("Breaking API Change in `{}`", b.symbol_name),
                    details: b.breaking_reason.unwrap_or_else(|| {
                        format!(
                            "Public symbol `{}` in `{}` modified (affects {} callers)",
                            b.symbol_name,
                            b.file_path,
                            b.direct_callers.len()
                        )
                    }),
                    line_hint: Some(format!("lines {}-{}", b.start_line, b.end_line)),
                });
                score = score.saturating_sub(20);
            }

            for h in projection.high_risk_symbols {
                if !h.is_breaking && h.pagerank_score > 0.04 {
                    findings.push(ReviewFinding {
                        category: "Architectural Risk & Blast Radius".to_string(),
                        severity: "MEDIUM".to_string(),
                        title: format!("High-Centrality Symbol Modified: `{}`", h.symbol_name),
                        details: format!(
                            "Symbol has PageRank score {:.4} and {} direct incoming callers.",
                            h.pagerank_score,
                            h.direct_callers.len()
                        ),
                        line_hint: Some(format!(
                            "{}:lines {}-{}",
                            h.file_path, h.start_line, h.end_line
                        )),
                    });
                    score = score.saturating_sub(10);
                }
            }
        }

        // 6. AST Code Smells & Complexity Anti-Patterns (run off async thread with a single reused parser)
        let root_for_smells = workspace_root.to_path_buf();
        let files_for_smells = target_files.clone();
        let detected_smells = tokio::task::spawn_blocking(move || {
            let mut all_smells = Vec::new();
            let mut extractor = crate::context::repomap::RepoMapExtractor::new();
            for f in &files_for_smells {
                let p = if Path::new(f).is_absolute() {
                    std::path::PathBuf::from(f)
                } else {
                    root_for_smells.join(f)
                };
                if let Ok(content) = std::fs::read_to_string(&p) {
                    let rel_path = p.strip_prefix(&root_for_smells).unwrap_or(&p);
                    let symbols = extractor.extract_file_symbols(&p).unwrap_or_default();
                    let smells = crate::context::smell_detector::AstSmellDetector::scan_code(
                        rel_path, &content, &symbols, None,
                    );
                    all_smells.extend(smells);
                }
            }
            all_smells
        })
        .await
        .unwrap_or_default();

        for smell in detected_smells {
            let normalized_sev = match smell.severity.as_str() {
                "HIGH" => "HIGH",
                "MEDIUM" | "ERROR" => "MEDIUM",
                _ => "LOW",
            };
            findings.push(ReviewFinding {
                category: "AST Code Health & Antipatterns".to_string(),
                severity: normalized_sev.to_string(),
                title: format!("{}: {}", smell.category.badge(), smell.message),
                details: smell.remediation,
                line_hint: Some(format!(
                    "{}:lines {}-{}",
                    smell.file_path, smell.start_line, smell.end_line
                )),
            });
            match normalized_sev {
                "HIGH" => score = score.saturating_sub(15),
                "MEDIUM" => score = score.saturating_sub(8),
                _ => Self::deduct_low_capped(&mut score, &mut low_deductions, 2),
            }
        }

        let summary = format!(
            "🛡️ **Multi-Agent Code Review Scorecard**\n\n\
            • **Overall Quality Score:** {} / 100\n\
            • **Files Evaluated:** {} file(s)\n\
            • **Total Findings:** {} ({} High, {} Medium, {} Low)\n",
            score,
            target_files.len(),
            findings.len(),
            findings.iter().filter(|f| f.severity == "HIGH").count(),
            findings.iter().filter(|f| f.severity == "MEDIUM").count(),
            findings.iter().filter(|f| f.severity == "LOW").count()
        );

        Ok(ReviewReport {
            total_score: score,
            files_audited: target_files.len(),
            findings,
            summary,
        })
    }

    /// Deducts points for `LOW` severity style/nesting notices while capping cumulative
    /// `LOW` deductions at 15 points so benign style notices cannot drive the score to 0.
    fn deduct_low_capped(score: &mut u32, low_deductions: &mut u32, points: u32) {
        const MAX_LOW_DEDUCTIONS: u32 = 15;
        let remaining = MAX_LOW_DEDUCTIONS.saturating_sub(*low_deductions);
        let applied = points.min(remaining);
        if applied > 0 {
            *low_deductions = low_deductions.saturating_add(applied);
            *score = score.saturating_sub(applied);
        }
    }

    /// Formats the review report into an interactive markdown string.
    pub fn format_report(report: &ReviewReport) -> String {
        let mut out = report.summary.clone();

        if report.findings.is_empty() {
            out.push_str("\n✨ **All checks passed cleanly!** No architectural defects, secret leaks, or logic risks found.\n");
            return out;
        }

        out.push_str("\n### Detailed Findings:\n\n");
        for (i, f) in report.findings.iter().enumerate() {
            let badge = match f.severity.as_str() {
                "HIGH" => "🔴 [HIGH]",
                "MEDIUM" => "🟡 [MEDIUM]",
                _ => "🔵 [LOW]",
            };

            out.push_str(&format!(
                "{}. {} **{}** ({})\n   • **Issue:** {}\n",
                i + 1,
                badge,
                f.title,
                f.category,
                f.details
            ));
            if let Some(ref hint) = f.line_hint {
                out.push_str(&format!("   • **Snippet:** `{}`\n", hint.trim()));
            }
            out.push('\n');
        }

        out
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn test_format_report_clean() {
        let report = ReviewReport {
            total_score: 100,
            files_audited: 5,
            findings: vec![],
            summary: "Scorecard Summary".to_string(),
        };
        let formatted = GitReviewer::format_report(&report);
        assert!(formatted.contains("All checks passed cleanly"));
    }

    #[test]
    fn test_format_report_with_findings() {
        let report = ReviewReport {
            total_score: 85,
            files_audited: 3,
            findings: vec![ReviewFinding {
                category: "Correctness".to_string(),
                severity: "HIGH".to_string(),
                title: "Potential Panic".to_string(),
                details: "Use error propagation".to_string(),
                line_hint: Some("+ let x = y.unwrap();".to_string()),
            }],
            summary: "Scorecard Summary".to_string(),
        };
        let formatted = GitReviewer::format_report(&report);
        assert!(formatted.contains("[HIGH]"));
        assert!(formatted.contains("Potential Panic"));
        assert!(formatted.contains("+ let x = y.unwrap();"));
    }

    #[test]
    fn test_deduct_low_capped_limits_cumulative_low_penalty() {
        let mut score = 100_u32;
        let mut low_deductions = 0_u32;
        for _ in 0..50 {
            GitReviewer::deduct_low_capped(&mut score, &mut low_deductions, 2);
        }
        assert_eq!(low_deductions, 15);
        assert_eq!(score, 85);
    }
}
